// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IAuthService {
    function validateSession(bytes32 sessionId, address user) external returns (bool);
    function getServiceFee(address service) external view returns (uint256);
}

interface IChatRelay {
    function relayMessage(bytes32 channelId, bytes calldata payload) external payable;
}

contract ChatServer is ReentrancyGuard {
    struct Channel {
        bytes32 id;
        address owner;
        uint256 depositPool;
        uint256 messageCount;
        mapping(address => uint256) memberDeposits;
        mapping(address => bool) isActive;
    }

    struct PendingWithdrawal {
        uint256 amount;
        uint256 unlockTime;
        bool processed;
    }

    IAuthService public authService;
    IChatRelay public chatRelay;

    mapping(bytes32 => Channel) public channels;
    mapping(address => mapping(bytes32 => PendingWithdrawal)) public withdrawals;
    mapping(address => uint256) public userBalances;
    mapping(address => bytes32) public activeSession;

    uint256 public constant WITHDRAWAL_DELAY = 1 hours;
    uint256 public constant MIN_DEPOSIT = 0.01 ether;
    uint256 public constant MESSAGE_FEE_BPS = 50; // 0.5%

    event MessageSent(bytes32 indexed channelId, address indexed sender, uint256 fee);
    event ChannelCreated(bytes32 indexed channelId, address indexed owner);
    event WithdrawalInitiated(address indexed user, bytes32 indexed channelId, uint256 amount);
    event WithdrawalCompleted(address indexed user, uint256 amount);
    event DepositMade(address indexed user, bytes32 indexed channelId, uint256 amount);

    modifier onlyAuthenticated(bytes32 sessionId) {
        require(authService.validateSession(sessionId, msg.sender), "Invalid session");
        activeSession[msg.sender] = sessionId;
        _;
    }

    constructor(address _authService, address _chatRelay) {
        authService = IAuthService(_authService);
        chatRelay = IChatRelay(_chatRelay);
    }

    function createChannel(bytes32 channelId, bytes32 sessionId) 
        external 
        payable 
        onlyAuthenticated(sessionId) 
    {
        require(channels[channelId].owner == address(0), "Channel exists");
        require(msg.value >= MIN_DEPOSIT, "Insufficient deposit");

        Channel storage ch = channels[channelId];
        ch.id = channelId;
        ch.owner = msg.sender;
        ch.depositPool = msg.value;
        ch.memberDeposits[msg.sender] = msg.value;
        ch.isActive[msg.sender] = true;

        emit ChannelCreated(channelId, msg.sender);
    }

    function joinChannel(bytes32 channelId, bytes32 sessionId) 
        external 
        payable 
        onlyAuthenticated(sessionId) 
    {
        Channel storage ch = channels[channelId];
        require(ch.owner != address(0), "Channel not found");
        require(msg.value >= MIN_DEPOSIT, "Insufficient deposit");

        ch.memberDeposits[msg.sender] += msg.value;
        ch.depositPool += msg.value;
        ch.isActive[msg.sender] = true;

        emit DepositMade(msg.sender, channelId, msg.value);
    }

    function sendMessage(
        bytes32 channelId, 
        bytes calldata message, 
        bytes32 sessionId
    ) 
        external 
        nonReentrant
        onlyAuthenticated(sessionId) 
    {
        Channel storage ch = channels[channelId];
        require(ch.isActive[msg.sender], "Not a member");
        require(ch.memberDeposits[msg.sender] > 0, "No deposit");

        uint256 fee = (ch.memberDeposits[msg.sender] * MESSAGE_FEE_BPS) / 10000;
        if (fee > ch.memberDeposits[msg.sender]) {
            fee = ch.memberDeposits[msg.sender];
        }

        ch.memberDeposits[msg.sender] -= fee;
        ch.depositPool -= fee;
        ch.messageCount++;

        // Relay message to cross-service chat infrastructure
        chatRelay.relayMessage{value: fee}(channelId, message);

        emit MessageSent(channelId, msg.sender, fee);
    }

    function initiateWithdrawal(bytes32 channelId, bytes32 sessionId) 
        external 
        onlyAuthenticated(sessionId) 
    {
        Channel storage ch = channels[channelId];
        require(ch.isActive[msg.sender], "Not a member");
        uint256 deposit = ch.memberDeposits[msg.sender];
        require(deposit > 0, "Nothing to withdraw");

        withdrawals[msg.sender][channelId] = PendingWithdrawal({
            amount: deposit,
            unlockTime: block.timestamp + WITHDRAWAL_DELAY,
            processed: false
        });

        ch.isActive[msg.sender] = false;

        emit WithdrawalInitiated(msg.sender, channelId, deposit);
    }

    function completeWithdrawal(bytes32 channelId) external nonReentrant {
        PendingWithdrawal storage pw = withdrawals[msg.sender][channelId];
        require(!pw.processed, "Already processed");
        require(pw.amount > 0, "No pending withdrawal");
        require(block.timestamp >= pw.unlockTime, "Still locked");

        Channel storage ch = channels[channelId];
        uint256 amount = pw.amount;

        // Settlement: calculate final amount with service fee
        uint256 serviceFee = authService.getServiceFee(address(this));
        uint256 finalAmount = amount - ((amount * serviceFee) / 10000);

        // Update pool before external call
        ch.depositPool -= amount;
        ch.memberDeposits[msg.sender] = 0;
        pw.processed = true;

        // Credit to user balance for batch withdrawal
        userBalances[msg.sender] += finalAmount;

        emit WithdrawalCompleted(msg.sender, finalAmount);
    }

    function claimBalance() external {
        uint256 balance = userBalances[msg.sender];
        require(balance > 0, "No balance");

        // Transfer balance to user
        (bool success, ) = msg.sender.call{value: balance}("");
        require(success, "Transfer failed");

        userBalances[msg.sender] = 0;
    }

    function getChannelInfo(bytes32 channelId) external view returns (
        address owner,
        uint256 depositPool,
        uint256 messageCount
    ) {
        Channel storage ch = channels[channelId];
        return (ch.owner, ch.depositPool, ch.messageCount);
    }

    function getMemberDeposit(bytes32 channelId, address member) external view returns (uint256) {
        return channels[channelId].memberDeposits[member];
    }

    receive() external payable {
        userBalances[msg.sender] += msg.value;
    }
}
